    "editorSpeech.sourceTooLarge": "このクリップは{size} MBで、上限の{max} MBを超えています。より小さい、または短いクリップを選んでください。クレジットは消費されていません。",
    "editorSpeech.sourceDense": "このクリップは{seconds}秒で{size} MBあり、1秒あたり約2 MBの上限を超えています。より短い、またはより圧縮されたクリップを選んでください。クレジットは消費されていません。",
    "editorSpeech.sourceUnreadable": "音声ツールはこのクリップのファイルを読み取れませんでした。別のクリップをお試しください。クレジットは消費されていません。",
    "editorSpeech.sourceFragmented": "このクリップはストリーミング形式のMP4で長さを測定できないため、音声ツールでは使えません。別のクリップを選ぶか、カメラロールから追加してください。クレジットは消費されていません。",
    "editorSpeech.sourceNoHash": "このクリップは、音声ツールが検証に必要とするフィンガープリントなしで保存されています。代わりにカメラロールから追加してください。クレジットは消費されていません。",
    "editorSpeech.sourceBadType": "音声ツールが読み取れるのはMP4とMOVのクリップだけで、このクリップは別の形式です。クレジットは消費されていません。",
    "editorSpeech.sourceNoAudio": "この動画には音声がないため、Best Cutが読み取る音声がありません。声が入ったクリップを選んでください。クレジットは消費されていません。",
    "editorSpeech.tooLong": "60秒以内のソースクリップを選んでください。",
